03","e6301024-0028-4000-9000-000000000804","e6301024-0028-4000-9000-000000000805","e6301024-0028-4000-9000-000000000806","e6301024-0028-4000-9000-000000000807","e6301024-0028-4000-9000-000000000808","e6301024-0028-4000-9000-000000000809","e6301024-0028-4000-9000-000000000810","e6301024-0028-4000-9000-000000000811","e6301024-0028-4000-9000-000000000812","e6301024-0029-4000-9000-000000000801","e6301024-0029-4000-9000-000000000802","e6301024-0029-4000-9000-000000000803","e6301024-0029-4000-9000-000000000804","e6301024-0029-4000-9000-000000000805","e6301024-0029-4000-9000-000000000806","e6301024-0029-4000-9000-000000000807","e6301024-0029-4000-9000-000000000808","e6301024-0029-4000-9000-000000000809","e6301024-0029-4000-9000-000000000810","e6301024-0029-4000-9000-000000000811","e6301024-0029-4000-9000-000000000812","e6301024-0030-4000-9000-000000000801","e6301024-0030-4000-9000-000000000802","e6301024-0030-4000-9000-000000000803","e6301024-0030-4000-9000-000000000804","e6301024-0030-4000-9000-000000000805","e6301024-0030-4000-9000-000000000806","e6301024-0030-4000-9000-000000000807","e6301024-0030-4000-9000-000000000808","e6301024-0030-4000-9000-000000000809","e6301024-0030-4000-9000-000000000810","e6301024-0030-4000-9000-000000000811","e6301024-0030-4000-9000-000000000814"]},"statuses":{"IN_PROGRESS":18,"COMPLETED":7,"PLANNED":5},"delayedTrips":4,"multiTruckTrips":10,"expectedGPSMarkers":28,"routeEligibleAssignments":["e6301024-0001-4000-9000-000000000101","e6301024-0001-4000-9000-000000000102","e6301024-0002-4000-9000-000000000101","e6301024-0003-4000-9000-000000000101","e6301024-0004-4000-9000-000000000101","e6301024-0004-4000-9000-000000000102","e6301024-0005-4000-9000-000000000101","e6301024-0007-4000-9000-000000000101","e6301024-0008-4000-9000-000000000101","e6301024-0008-4000-9000-000000000102","e6301024-0009-4000-9000-000000000101","e6301024-0010-4000-9000-000000000101","e6301024-0010-4000-9000-000000000102","e6301024-0011-4000-9000-000000000101","e6301024-0013-4000-9000-000000000101","e6301024-0014-4000-9000-000000000101","e6301024-0014-4000-9000-000000000102","e6301024-0015-4000-9000-000000000101","e6301024-0017-4000-9000-000000000101","e6301024-0018-4000-9000-000000000101","e6301024-0018-4000-9000-000000000102","e6301024-0019-4000-9000-000000000101","e6301024-0019-4000-9000-000000000102","e6301024-0021-4000-9000-000000000101","e6301024-0022-4000-9000-000000000101","e6301024-0024-4000-9000-000000000101","e6301024-0024-4000-9000-000000000102","e6301024-0025-4000-9000-000000000101","e6301024-0025-4000-9000-000000000102","e6301024-0026-4000-9000-000000000101","e6301024-0027-4000-9000-000000000101","e6301024-0030-4000-9000-000000000101","e6301024-0030-4000-9000-000000000102"]}$manifest$::jsonb;
 actor uuid := (manifest->>'reviewer')::uuid;
 owned uuid[]; trip_ids uuid[]; live_ids uuid[]; batch_ids uuid[]; batch_start integer;
 master_tables text[] := ARRAY['customers','trucking_companies','products','trip_types','warehouses','trucks','drivers','customer_stores'];
 relation record; table_name text; tag_column text; unexpected boolean; impact jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ALZHEN_DEMO30_V1'));
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=actor AND role='ADMIN') THEN RAISE EXCEPTION 'Existing Admin required'; END IF;
 SELECT array_agg(item.value::uuid) INTO owned FROM jsonb_each(manifest->'ids') entry CROSS JOIN LATERAL jsonb_array_elements_text(entry.value) item(value);
 SELECT array_agg(value::uuid) INTO trip_ids FROM jsonb_array_elements_text(manifest->'ids'->'trips') item(value);
 IF EXISTS(SELECT 1 FROM public.trips WHERE id=ANY(trip_ids) AND (coalesce(remarks,'') NOT LIKE '%[ALZHEN_DEMO30_V1]%' OR dispatch_number NOT LIKE 'DEMO30-20261024-%')) THEN RAISE EXCEPTION 'Demo identity changed'; END IF;
 IF EXISTS(SELECT 1 FROM public.driver_trip_updates WHERE driver_id=ANY(owned) AND (NOT id=ANY(owned) OR coalesce(notes,'') NOT LIKE '%[ALZHEN_DEMO30_V1]%' OR pod_image_path IS NOT NULL OR pod_image_url IS NOT NULL)) THEN RAISE EXCEPTION 'New/attached driver activity; cleanup blocked'; END IF;
 IF EXISTS(SELECT 1 FROM public.products WHERE id=ANY(owned) AND photo_path IS NOT NULL) THEN RAISE EXCEPTION 'A demo product now has an image; review attachments before cleanup'; END IF;
 -- Includes SET NULL references: cleanup must never change real operational rows.
 FOR relation IN
  SELECT cn.nspname child_schema,cc.relname child_table,ca.attname child_column,pn.nspname parent_schema,pc.relname parent_table,pa.attname parent_column
  FROM pg_constraint c JOIN pg_class cc ON cc.oid=c.conrelid JOIN pg_namespace cn ON cn.oid=cc.relnamespace JOIN pg_class pc ON pc.oid=c.confrelid JOIN pg_namespace pn ON pn.oid=pc.relnamespace
  JOIN pg_attribute ca ON ca.attrelid=cc.oid AND ca.attnum=c.conkey[1] JOIN pg_attribute pa ON pa.attrelid=pc.oid AND pa.attnum=c.confkey[1]
  WHERE c.contype='f' AND pn.nspname='public' AND pc.relname=ANY(master_tables) AND array_length(c.conkey,1)=1
 LOOP
  IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=relation.child_schema AND table_name=relation.child_table AND column_name='id') THEN RAISE EXCEPTION 'Unknown referencing table % requires review',relation.child_table; END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM %I.%I child JOIN %I.%I parent ON child.%I=parent.%I WHERE parent.id=ANY($1) AND NOT(child.id::text=ANY($2)))',relation.child_schema,relation.child_table,relation.parent_schema,relation.parent_table,relation.child_column,relation.parent_column) INTO unexpected USING owned,owned::text[];
  IF unexpected THEN RAISE EXCEPTION 'A non-demo record in % uses demo references',relation.child_table; END IF;
 END LOOP;
 SELECT coalesce(array_agg(id),'{}'::uuid[]) INTO live_ids FROM public.trips WHERE id=ANY(trip_ids);
 IF cardinality(live_ids)>0 THEN
  FOR table_name IN SELECT jsonb_object_keys(manifest->'ids') LOOP
   IF table_name=ANY(master_tables) OR table_name='trips' THEN CONTINUE; END IF;
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE trip_id=ANY($1) AND NOT id=ANY($2))',table_name) INTO unexpected USING live_ids,owned;
   IF unexpected THEN RAISE EXCEPTION 'New operational rows in %; cleanup blocked',table_name; END IF;
  END LOOP;
  -- The existing deletion workflow accepts at most twenty physical trips per call.
  -- Both batches remain inside this one transaction: any blocker rolls back everything.
  FOR batch_start IN 1..cardinality(live_ids) BY 20 LOOP
   batch_ids:=live_ids[batch_start:least(batch_start+19,cardinality(live_ids))];
   impact:=public.preview_whole_trip_deletion_v1(batch_ids,actor);
   IF impact IS NULL OR jsonb_array_length(impact->'blockers')<>0 OR EXISTS(SELECT 1 FROM jsonb_each_text(impact->'counts') c WHERE c.value::numeric>0 AND c.key NOT IN ('trip_stops','trip_line_items','trip_truck_assignments','trip_assignment_stops','trip_cargo_allocations','trip_events','driver_trip_updates','loading_reports','unloading_reports','incidents','cached_routes')) THEN RAISE EXCEPTION 'Deletion impact contains additional data/attachments'; END IF;
   PERFORM public.delete_whole_trips_v1(batch_ids,actor);
  END LOOP;
 END IF;
 FOREACH table_name IN ARRAY master_tables LOOP
  tag_column:=CASE WHEN table_name='trip_types' THEN 'description' ELSE 'notes' END;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE id=ANY($1) AND coalesce(%I,'''') NOT LIKE ''%%[ALZHEN_DEMO30_V1]%%'')',table_name,tag_column) INTO unexpected USING owned;
  IF unexpected THEN RAISE EXCEPTION 'Ownership tag changed in %',table_name; END IF;
 END LOOP;
 DELETE FROM public.drivers WHERE id=ANY(owned);
 DELETE FROM public.trucks WHERE id=ANY(owned);
 DELETE FROM public.customer_stores WHERE id=ANY(owned);
 DELETE FROM public.products WHERE id=ANY(owned);
 DELETE FROM public.warehouses WHERE id=ANY(owned);
 DELETE FROM public.trip_types WHERE id=ANY(owned);
 DELETE FROM public.customers WHERE id=ANY(owned);
 DELETE FROM public.trucking_companies WHERE id=ANY(owned);
END;
$cleanup30$;
COMMIT;
